// Verifies the OS signature: HMAC-SHA256(secret, `${timestamp}.${nonce}.${body}`), max 5 minutes old.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and DP_SIGNING_SECRET (same value as N8N_SIGNING_SECRET in the OS).
const crypto = require('crypto');
const item = $input.first();
const h = item.json.headers || {};
const secret = $env.DP_SIGNING_SECRET || '';
const raw = item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
const ts = String(h['x-dp-timestamp'] || ''), nonce = String(h['x-dp-nonce'] || ''), sig = String(h['x-dp-signature'] || '');
let ok = Boolean(secret) && /^\d{9,11}$/.test(ts) && nonce.length >= 16 && nonce.length <= 128 && /^[0-9a-f]{64}$/.test(sig)
  && Math.abs(Math.floor(Date.now() / 1000) - Number(ts)) <= 300;
if (ok) {
  const expected = crypto.createHmac('sha256', secret).update(`${ts}.${nonce}.${raw}`).digest();
  const given = Buffer.from(sig, 'hex');
  ok = given.length === expected.length && crypto.timingSafeEqual(given, expected);
}
let payload = {};
try { payload = JSON.parse(raw); } catch (e) { ok = false; }
const runOk = ok && /^[0-9a-f-]{36}$/.test(String(payload.run_id || '')) && /^[0-9a-f-]{36}$/.test(String(payload.organization_id || ''));
return [{ json: { ok: runOk, run_id: payload.run_id, organization_id: payload.organization_id, input: payload.input || {} } }];

const inr = (m) => '₹' + (Number(m || 0) / 100).toLocaleString('en-IN', { maximumFractionDigits: 0 });
const s = $('Verify signature').first().json.input;
const lines = [
  `Open deals: ${s.open_deals ?? 0} (${inr(s.open_pipeline_minor)} in INR pipeline)`,
  `Meetings today: ${s.meetings_today ?? 0}`,
  `Overdue tasks: ${s.tasks_overdue ?? 0}`,
  `Ledger entries waiting for approval: ${s.ledger_awaiting_approval ?? 0}`,
  `Bills waiting for review: ${s.bills_awaiting_review ?? 0}`,
];
return [{ json: { subject: `${s.company}: summary for ${s.date}`, text: lines.join('\n') + '\n\nCounts come from records in Diwani Parivaar OS. Open the OS to act on any of them.' } }];

// Signs the result for the OS callback exactly as the OS signs its webhooks.
const crypto = require('crypto');
const run = $('Verify signature').first().json;
const failed = $input.first().json.error;
const body = JSON.stringify({
  run_id: run.run_id,
  organization_id: run.organization_id,
  status: failed ? 'failed' : 'succeeded',
  execution_id: String($execution.id),
  ...(failed ? { error: String(failed.message || failed).slice(0, 1900) } : {}),
});
const ts = Math.floor(Date.now() / 1000);
const nonce = crypto.randomBytes(16).toString('hex');
const signature = crypto.createHmac('sha256', $env.DP_SIGNING_SECRET).update(`${ts}.${nonce}.${body}`).digest('hex');
return [{ json: { body, ts: String(ts), nonce, signature } }];
